from datetime import datetime

from billing.clock import expiry, from_timestamp, is_expired


def test_past_dates_are_expired():
    assert is_expired(datetime(2000, 1, 1))


def test_future_dates_are_not_expired():
    assert not is_expired(expiry(2))


def test_epoch():
    assert from_timestamp(0) == datetime(1970, 1, 1)
